#include "symrep_bootstrap.hpp"
using namespace symrep;
int main(int argc,char**argv){try{require(argc==2,"outputdirectory");fs::path out=argv[1];auto begin=std::chrono::steady_clock::now();auto p=read_matrix(out/"boundary/DC/collinear/first_w6.wxf");auto s=mul(read_matrix(out/"suffix_TR92_to_TF175.wxf"),read_matrix(out/"boundary/DC/suffix_TF175_raw2.wxf"));auto st=transpose(s);std::vector<size_t> counts(p.ncol);for(const auto&r:p.rows)for(auto c:r.index_span())++counts[c];std::sort(counts.begin(),counts.end());std::array<size_t,4>limits{64,256,1024,4096};std::array<size_t,4>total{};size_t pairs=0,terms=0;std::ofstream j(out/"boundary_discovery_profile.json");j<<"{\"scope\":\"Target-free homogeneous raw support cost for available double-collinear spurious suffix-pair equations; one extra source term conservatively counted. No restart or scheduling change.\",\"prefix_dimensions\":["<<p.nrow<<","<<p.ncol<<"],\"prefix_nonzeros\":"<<p.nnz()<<",\"prefix_column_support_min_median_max\":["<<counts.front()<<","<<counts[counts.size()/2]<<","<<counts.back()<<"],\"suffix_TR_dimensions\":[92,484],\"spurious_pair_blocks\":[";bool first=true;
 for(size_t c=0;c<st.nrow;++c)if((c/22>=6||c%22>=6)&&st[c].nnz()){size_t n=st[c].nnz();if(!first)j<<",";first=false;++pairs;terms+=n*p.nnz();j<<"{\"pair\":["<<c/22+1<<","<<c%22+1<<"],\"suffix_support\":"<<n<<",\"rows_below_64_256_1024_4096_terms\":[";for(size_t k=0;k<4;++k){size_t ct=std::upper_bound(counts.begin(),counts.end(),(limits[k]-1)/n)-counts.begin();total[k]+=ct;if(k)j<<",";j<<ct;}j<<"]}";}
 j<<"],\"active_spurious_pair_count\":"<<pairs<<",\"raw_equation_count\":"<<pairs*p.ncol<<",\"raw_product_terms\":"<<terms<<",\"total_rows_below_64_256_1024_4096_terms\":[";for(size_t k=0;k<4;++k){if(k)j<<",";j<<total[k];}j<<"],\"seconds\":"<<seconds(begin)<<",\"F4_target_read\":false}\n";std::cout<<"PROFILE pairs="<<pairs<<" rows="<<pairs*p.ncol<<" terms="<<terms<<" short=";for(auto n:total)std::cout<<n<<",";std::cout<<" seconds="<<seconds(begin)<<std::endl;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
